下面代码采用动态规划求解零钱兑换问题：给定多种硬币，第 i 种硬币的面值为 `coins[i - 1]`，目标金额为 amt，每种硬币可以重复选取，求能够凑出目标金额的最少硬币数量；如果不能凑出目标金额，返回 -1。（ ）
```cpp
int coinChangeDPComp(vector<int> &coins, int amt) {
    int n = coins.size();
    int MAX = amt + 1;

    vector<int> dp(amt + 1, MAX);
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int a = 1; a <= amt; a++) {
            if (coins[i - 1] > a)
                dp[a] = dp[a];
            else
                dp[a] = min(dp[a], dp[a - coins[i - 1]] + 1);
        }
    }
    return dp[amt] != MAX ? dp[amt] : -1;
}
```

questions.explanation:
划分方案只与各组人数有关，是有序/无序均可的完全背包计数型 DP。设 f[i] 为划分 i 人的最大积极度和，转移 f[i] = max(f[i−k] + a[k])（1 ≤ k ≤ i）。因为 a[k] 可重复取（多个同人数组），按人数从 1 到 n 递推即可。样例 1：3+3+... 分成 {3,3,...}? 实为 3+3+2+2? 最优 {3,3,2,2}: a3+a3+a2+a2=3+3+5+5? 官方样例 4→10 即 5+5（两个 2 人组）。样例 2：{3,3,2} 5+5+2=12。时间复杂度 O(n²)。

参考程序：
```cpp
#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 1005;

int n;
int a[N];

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
        for (int j = 1; j < i; j++)
            a[i] = max(a[i], a[j] + a[i - j]);
    }
    printf("%d\n", a[n]);
    return 0;
}
```

结点 k 的父结点是其最大真因数 k/p（p 为 k 的最小质因子）。把每个数除质因数到 1 的链视为树上路径：结点链为 x, x/p₁, x/(p₁p₂), ..., 1。两结点的最近公共祖先即两条除因子链首次相同的数，距离 = 各自步数之和（链上每除一次恰走一条边），双指针在两条因子链上同步推进即可。样例 2：120→60→30→15→5→1 与 650→325→65→13→1，公共祖先为 1，距离 = 5+4 = 9。单次询问 O(log x + log y)。

参考程序：
```cpp
#include <cstdio>
#include <algorithm>
using namespace std;

const int N = 50;

int q;
int a[N], cnta;
int b[N], cntb;
int f[N], t;

void factorize(int x, int a[], int &cnt) {
    a[0] = x;
    t = 0;
    for (int i = 2; i * i <= x; i++)
        while (x % i == 0) {
            f[++t] = i;
            x /= i;
        }
    if (x > 1)
        f[++t] = x;
    for (int i = 1; i <= t; i++)
        a[i] = a[i - 1] / f[i];
    cnt = t;
}

int main() {
    scanf("%d", &q);
    while (q--) {
        int x, y;
        scanf("%d%d", &x, &y);
        factorize(x, a, cnta);
        factorize(y, b, cntb);
        int px = 0, py = 0;
        while (a[px] != b[py]) {
            if (a[px] > b[py])
                px++;
            else
                py++;
        }
        printf("%d\n", px + py);
    }
    return 0;
}
```
